plot_scatter <- function(raw_x, raw_y, smooth_y, timescale, y_label, title = NULL) {
  plot(
    x = raw_x,
    y = raw_y,
    type = "p",
    col = "red",
    ylab = y_label,
    xlab = "Time (10 ky)",
    xlim = c(0, 400),
    main = title
  )

  lines(x = timescale, y = smooth_y, col = "black")

  legend(
    "top",
    c("x = raw data", "y = smooth data"),
    col = c("red", "black"),
    pch = c(16, NA),
    lty = c(NA, 1),
    bty = "n",
    horiz = TRUE
  )

  invisible(NULL)
}

